const i = $('When Called').first().json;
const c = $input.first().json;
const channel = String(i.channel || 'whatsapp');
const phone = c.phone || '';
const name = String(i.name || c.vname || c.cname || '');
const WEB = "WEBSITE CHAT RULES\n- The visitor is on almutawabh.com. You may offer up to 5 quick-choice buttons by writing each choice as [[choice text]] on the last line (e.g. [[\ud83d\udd4b \u0639\u0645\u0631\u0629]] [[\u2708\ufe0f \u062a\u0630\u0627\u0643\u0631 \u0637\u064a\u0631\u0627\u0646]]). Use them for destinations found, yes/no, or next steps. You may use **bold** and links.\n- The visitor may be anonymous. Known contact: {phone}. Before saving a trip request or a booking, ask for their name and WhatsApp number, then call save_contact.\n- Passport/ID photos: ask them to send them on WhatsApp https://wa.me/97333444748 (same office, same team).\n- Messages starting with [\u0637\u0644\u0628 \u0645\u0646 \u0646\u0645\u0648\u0630\u062c \u0627\u0644\u0634\u0627\u062a] come from the chat's quick form; treat them as the customer's request and continue from there (ask only what is missing).";
const WA = "WHATSAPP RULES\n- You are replying on the office WhatsApp number. The customer's phone is known: {phone}. Plain text only (WhatsApp formatting *bold* is fine). No [[buttons]].";
const channelRules = (channel === 'web' ? WEB : WA).replace('{phone}', phone || 'not given yet');
const notes = c.notes ? ('Known customer profile (from previous conversations): ' + c.notes + '\n\n') : '';
const promptText = notes + 'Conversation history:\n' + (c.history || '(none)') + '\n\nCustomer (' + (name || 'visitor') + ') new message: ' + String(i.message || '');
return [{ json: { channel, contact: String(i.contact || ''), phone, name, channelRules, promptText } }];

